  name: string,
  version: number,
  defaultValue: T,
): Context<T> {
  const Context = createSharedContext(name, version, defaultValue);
  if (!reactResets.has(Context as Context<unknown>)) {
    reactResets.set(Context as Context<unknown>, children => (
      <Context value={defaultValue}>{children}</Context>
