  if (typeof rate === 'number' && rate !== next.playbackRate) {
    next.playbackRate = rate;
  }
  if (saved.playState === 'paused' && next.playState !== 'paused') {
    next.pause();
  } else if (saved.playState !== 'paused' && next.playState === 'paused') {
    next.play();
  }
