  doc: Document,
  text: string,
): ((x: number) => number) | null {
  const view = doc.defaultView;
  if (
    typeof view?.Animation !== 'function' ||
    typeof view.KeyframeEffect !== 'function'
  ) {
    return null;
  }
  let animation: Animation;
  try {
    animation = new view.Animation(
      new view.KeyframeEffect(null, null, {
        duration: 1000,
        easing: text,
        fill: 'both',
      }),
      null,
    );
