  element: Element,
  {
    duration,
    easing,
  }: {readonly duration?: DurationVarName; readonly easing?: EaseVarName},
): ResolvedTiming {
  const style = element.ownerDocument.defaultView?.getComputedStyle(element);
  if (style == null) {
    return {ms: null, points: null};
